#include <iostream>
#include <vector>
using namespace std;

using int64 = long long;

int64 modPow(int64 base, int64 exp, int64 mod) {
    int64 result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b, p, x;
    cin >> a >> b >> p >> x;

    int64 value = p - 1;
    vector<int64> primeFactors;

    for (int64 q = 2; q * q <= value; ++q) {
        if (value % q == 0) {
            primeFactors.push_back(q);
            while (value % q == 0) value /= q;
        }
    }
    if (value > 1) primeFactors.push_back(value);

    int64 order = p - 1;
    for (int64 q : primeFactors) {
        while (order % q == 0 && modPow(a, order / q, p) == 1) {
            order /= q;
        }
    }

    const int64 period = p * order;
    const int64 inverseOrder = modPow(order % p, p - 2, p);
    const int64 inverseA = modPow(a, p - 2, p);

    int64 answer = 0;
    int64 requiredResidue = b;

    for (int64 r = 0; r < order; ++r) {
        int64 difference = (requiredResidue - r) % p;
        if (difference < 0) difference += p;

        int64 k = difference * inverseOrder % p;
        int64 first = r + order * k;

        if (first > 0 && first <= x) {
            answer += (x - first) / period + 1;
        }

        requiredResidue = requiredResidue * inverseA % p;
    }

    cout << answer << '\n';
    return 0;
}

