    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b, p, x;
    cin >> a >> b >> p >> x;

    const int64 period = p * (p - 1);
    const int64 fullCycles = x / period;
    const int64 remainder = x % period;

    int64 answer = fullCycles * (p - 1);
    const int64 inverseA = modPow(a, p - 2, p);
